helpers.makeAllResolvableTokens:
function makeAllResolvableTokens(value: { added: string; modified: string; deleted: string }): Tokens {
  return create(TokensSchema, {
    palette: { green: '#00ff00' },
    roles: {
      diff_added: value.added,
      diff_modified: value.modified,
      diff_deleted: value.deleted,
    },
  });
}

helpers.makeTokensWithUnresolved:
function makeTokensWithUnresolved(unresolved: readonly string[]): Tokens {
  const roles: { [key: string]: string } = {
    diff_added: '#11aa11',
    diff_modified: '#aa11aa',
    diff_deleted: '#1111aa',
  };
  for (const role of unresolved) {
    delete roles[role];
  }
  return create(TokensSchema, { roles });
}

helpers.resolvedRoleValue:
function resolvedRoleValue(value: string): string {
  return value === '$palette.green' ? '#00ff00' : value;
}

helpers.expectedDesaturated:
function expectedDesaturated(color: string): string {
    const red: number = parseInt(color.slice(1, 3), 16);
    const green: number = parseInt(color.slice(3, 5), 16);
    const blue: number = parseInt(color.slice(5, 7), 16);
    const lightness: number = Math.floor((Math.max(red, green, blue) + Math.min(red, green, blue)) / 2);
    const channel: string = lightness.toString(16).padStart(2, '0');
    return `#${channel}${channel}${channel}`;
}

helpers.greyHex:
function greyHex(channel: number): string {
    const hex: string = channel.toString(16).padStart(2, '0');
    return `#${hex}${hex}${hex}`;
}

helpers.rgbHex:
function rgbHex(channels: [number, number, number]): string {
    const red: string = channels[0].toString(16).padStart(2, '0');
    const green: string = channels[1].toString(16).padStart(2, '0');
    const blue: string = channels[2].toString(16).padStart(2, '0');
    return `#${red}${green}${blue}`;
}

helpers.expectedRotateHue:
function expectedRotateHue(color: string, degrees: number): string {
  const red: number = parseInt(color.slice(1, 3), 16) / 255;
  const green: number = parseInt(color.slice(3, 5), 16) / 255;
  const blue: number = parseInt(color.slice(5, 7), 16) / 255;
  const maximum: number = Math.max(red, green, blue);
  const minimum: number = Math.min(red, green, blue);
  const lightness: number = (maximum + minimum) / 2;
  const difference: number = maximum - minimum;
  let hue: number = 0;
  let saturation: number = 0;
  if (difference !== 0) {
    saturation = difference / (1 - Math.abs(2 * lightness - 1));
    if (maximum === red) {
      hue = 60 * (((green - blue) / difference) % 6);
    } else if (maximum === green) {
      hue = 60 * ((blue - red) / difference + 2);
    } else {
      hue = 60 * ((red - green) / difference + 4);
    }
  }
  hue = ((hue + degrees) % 360 + 360) % 360;
  const hueToRgb = (p: number, q: number, t: number): number => {
    let normalized: number = t;
    if (normalized < 0) normalized += 1;
    if (normalized > 1) normalized -= 1;
    if (normalized < 1 / 6) return p + (q - p) * 6 * normalized;
    if (normalized < 1 / 2) return q;
    if (normalized < 2 / 3) return p + (q - p) * (2 / 3 - normalized) * 6;
    return p;
  };
  const chroma: number = (1 - Math.abs(2 * lightness - 1)) * saturation;
  const q: number = lightness < 0.5 ? lightness * (1 + saturation) : lightness + saturation - lightness * saturation;
  const p: number = 2 * lightness - q;
  const normalizedHue: number = hue / 360;
  const outputRed: number = difference === 0 ? lightness : hueToRgb(p, q, normalizedHue + 1 / 3);
  const outputGreen: number = difference === 0 ? lightness : hueToRgb(p, q, normalizedHue);
  const outputBlue: number = difference === 0 ? lightness : hueToRgb(p, q, normalizedHue - 1 / 3);
  const toHex = (channel: number): string => Math.round(channel * 255).toString(16).padStart(2, '0');
  void chroma;
  return `#${toHex(outputRed)}${toHex(outputGreen)}${toHex(outputBlue)}`;
}

