  if (decoration.color !== undefined) expect(result.decorations[index]?.color).toBe(diffColorFor(decoration.color, ChangeType.MODIFIED));
});
if (value.stroke?.paint.case === "color") expect(value.stroke.paint.value).toBe("#336699");
