helpers.emptyDiagram:
function emptyDiagram(): Diagram {
  return create(DiagramSchema, { id: 'diagram' });
}

helpers.emptyLaidOutDiagram:
function emptyLaidOutDiagram(id: string): LaidOutDiagram {
  return create(LaidOutDiagramSchema, { id });
}

helpers.emptyStylesheet:
function emptyStylesheet(): Stylesheet {
  return create(StylesheetSchema, { schemaVersion: 1 });
}
